import html
def make_report(result):
 a,b=result['a'],result['b'];sa,sb=result['scores_a'],result['scores_b'];u=result['user']
 rows=''.join(f'<tr><td>{k}</td><td>{sa[k]:.0f}</td><td>{sb[k]:.0f}</td><td>{sb[k]-sa[k]:+.0f}</td></tr>' for k in sa)
 horizons=''.join('<div class=card><h3>'+h+'</h3><ul>'+''.join(f'<li><b>{label}:</b> {html.escape(text)}</li>' for label,text,_ in items)+'</ul></div>' for h,items in result['horizons'].items())
 def names(ev,key):return ', '.join(ev['features'][key][:6]) or 'No named examples returned'
 prop=result.get('property_b');prop_txt='No current-listing sample supplied.' if not prop else (html.escape(prop.get('error','')) if 'error' in prop else f"{prop['count']} sampled listings; {prop['within']} within budget; median asking price {'unavailable' if prop['median'] is None else '£'+format(prop['median'],',.0f')}; coverage: {prop['coverage']}.")
 journey=result.get('journey_b');journey_txt='No regular destination supplied.' if not journey else f"Approximate road journey from destination: {journey['miles']:.0f} miles / {journey['minutes']:.0f} minutes without live traffic."
 headlines=''.join(f'<li>{html.escape(x)}</li>' for x in result['evidence_b']['headlines']) or '<li>No recent headlines returned</li>'
 sources=''.join(f'<li>{"Available" if s["ok"] else "Unavailable"}: <b>{s["source"]}</b> – {s["detail"]}</li>' for s in result['statuses'])
 return f'''<!doctype html><html><head><meta charset=utf-8><style>@page{{size:A4;margin:14mm}}body{{font-family:Segoe UI,Arial;background:#edf4f1;margin:0;color:#17332d;line-height:1.5}}main{{max-width:980px;margin:auto;background:white}}header{{padding:42px;background:linear-gradient(120deg,#123f52,#0f766e);color:white}}section{{padding:25px 40px;border-bottom:1px solid #ddd}}h1{{font-size:40px;margin:0}}h2{{color:#0f766e}}.grid,.horizons{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}.card{{background:#f6faf8;padding:16px;border-radius:14px}}table{{width:100%;border-collapse:collapse}}th,td{{padding:9px;border-bottom:1px solid #ddd;text-align:left}}th{{background:#eff8f5}}.callout{{font-size:20px;background:#fff8e8;border-left:6px solid #e8a838;padding:17px}}@media print{{section{{break-inside:avoid}}}}</style></head><body><main><header><div>PERSONALISED LOCATION LIFESTYLE REPORT</div><h1>Location Lifestyle AI</h1><p>{html.escape(a['label'])} → {html.escape(b['label'])}</p></header><section><h2>Bottom line</h2><p class=callout>The destination evidence is strongest in {max(sb,key=sb.get)} and weakest in {min(sb,key=sb.get)}. Property availability is labelled separately and is never inferred from amenity data.</p><p><b>Household:</b> {u['household']}; {u['life_stage']}; budget £{u['budget']:,.0f}. <b>Must-haves:</b> {html.escape(u['must'] or 'not stated')}. <b>Deal-breakers:</b> {html.escape(u['avoid'] or 'not stated')}.</p></section><section><h2>Lifestyle fingerprint</h2><table><tr><th>Dimension</th><th>Current</th><th>Destination</th><th>Difference</th></tr>{rows}</table></section><section><h2>Next chapter fit</h2><div class=horizons>{horizons}</div></section><section><h2>Property reality</h2><p>{prop_txt}</p></section><section><h2>Stay active</h2><p>{html.escape(names(result['evidence_b'],'Active life'))}</p><h2>Blue-space life</h2><p>{html.escape(names(result['evidence_b'],'Blue space'))}</p></section><section><h2>Curious mind and culture</h2><p>{html.escape(names(result['evidence_b'],'Culture'))}</p><h2>Find your tribe</h2><p>{html.escape(names(result['evidence_b'],'Community'))}</p></section><section><h2>Family visit test</h2><p>{html.escape(names(result['evidence_b'],'Family'))}</p><h2>Outdoors</h2><p>{html.escape(names(result['evidence_b'],'Green space'))}</p></section><section><h2>Daily practicality</h2><p><b>Shops:</b> {html.escape(names(result['evidence_b'],'Shops'))}</p><p><b>Healthcare:</b> {html.escape(names(result['evidence_b'],'Healthcare'))}</p><p><b>Travel:</b> {html.escape(names(result['evidence_b'],'Travel'))}</p></section><section><h2>Relationship geography</h2><p>{journey_txt}</p></section><section><h2>Local pulse</h2><ul>{headlines}</ul><p>Headlines are search results, not sentiment analysis.</p></section><section><h2>Source health</h2><ul>{sources}</ul><p>Unavailable sources are excluded rather than converted into zero.</p></section></main></body></html>'''
